import { mkdirSync, writeFileSync, readFileSync, rmSync, cpSync, existsSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fork, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const base = resolve('.research/2026-11-28-multi-harness-audit/notes/run');
const source = process.env.AUDIT_SOURCE_ROOT;
if (!source) throw new Error('Set AUDIT_SOURCE_ROOT to scripts/source.mjs local baseline checkout');
const slug = '2026-01-01-probe';
if (process.argv[2] === 'worker') {
  const { openWindow } = await import(join(source, 'scripts/hooks/docs.mjs'));
  process.send('ready');
  process.once('message', () => {
    openWindow(base, [slug], process.argv[3], 'fixture');
    process.send('done');
    process.disconnect();
  });
} else {
  mkdirSync(join(base, '.research', slug, 'notes/web'), { recursive: true });
  mkdirSync(join(base, 'research', slug), { recursive: true });
  writeFileSync(join(base, 'research', slug, 'index.html'), '<html>fixture</html>');
  writeFileSync(join(base, '.research', slug, 'notes/web', 'large.txt'), 'x'.repeat(16 * 1024 * 1024));
  const { closeWindow, readWindow } = await import(join(source, 'scripts/hooks/docs.mjs'));
  let lost = 0, premature = 0;
  for (let trial = 0; trial < 10; trial++) {
    rmSync(join(base, '.research/lens-window.json'), { force: true });
    const children = ['lens-numbers', 'lens-reader'].map(role => fork(fileURLToPath(import.meta.url), ['worker', role], { stdio: ['ignore', 'ignore', 'inherit', 'ipc'] }));
    await Promise.all(children.map(c => new Promise(r => c.once('message', r))));
    const done = Promise.all(children.map(c => new Promise(r => c.once('message', r))));
    children.forEach(c => c.send('go'));
    await done;
    const pending = readWindow(base)?.pending || [];
    if (pending.length !== 2) {
      lost++;
      closeWindow(base, pending[0]);
      if (!readWindow(base)) premature++;
    }
  }
  const bin = join(base, 'bin'); mkdirSync(bin, { recursive: true });
  const git = '#!/usr/bin/env node\nif (process.argv[2] === "rev-parse") console.log(process.env.PROBE_ROOT); else if (process.argv[2] === "status") console.log("?? research/2026-01-01-probe/index.html");\n';
  writeFileSync(join(bin, 'git'), git, { mode: 0o755 });
  cpSync(join(source, 'scripts'), join(base, 'scripts'), { recursive: true });
  writeFileSync(join(base, '.research/active.json'), JSON.stringify({ runId: 'fixture', harness: 'codex', state: 'running' }));
  // These files are fixture state, not this research run's review records.
  writeFileSync(join(base, '.research/lens-window.json'), JSON.stringify({ opened: new Date().toISOString(), pending: ['lens-reader'], files: {} }));
  const decisions = {};
  for (const prefix of ['', './', 'research/../']) {
    const target = prefix + `research/${slug}/index.html`;
    const event = { hook_event_name: 'PreToolUse', cwd: base, agent_type: 'researcher', session_id: 'fixture', tool_name: 'apply_patch', tool_input: { command: `*** Begin Patch\n*** Update File: ${target}\n@@\n-fixture\n+changed\n*** End Patch` } };
    const r = spawnSync('node', [join(base, 'scripts/hooks/pretool.mjs'), '--harness=codex', '--role=researcher'], { input: JSON.stringify(event), encoding: 'utf8', env: { ...process.env, PATH: bin + ':' + process.env.PATH, PROBE_ROOT: base, CODEX_HOME: join(base, 'empty-home') } });
    decisions[target] = { status: r.status, output: JSON.parse(r.stdout) };
  }
  console.log(JSON.stringify({ race: { trials: 10, lostPending: lost, prematureClose: premature, enlargedFixtureBytes: 16 * 1024 * 1024 }, pathDecisions: decisions }, null, 2));
}
